<?php require __DIR__.'/partials/header.php';$rows=$db->query('SELECT * FROM players ORDER BY points_avg DESC')->fetchAll(); ?><section class="page-hero"><div class="wrap"><span class="eyebrow">NUMERI IN CAMPO</span><h1>LE <em>STATISTICHE</em></h1><p>Indicatori individuali dimostrativi, aggiornabili dal database.</p></div></section><section class="wrap section"><div class="stat-grid"><div><b><?= $rows?number_format(max(array_column($rows,'points_avg')),1):'—' ?></b><small>MIGLIOR REALIZZATORE · PPG</small></div><div><b><?= $rows?number_format(max(array_column($rows,'assists_avg')),1):'—' ?></b><small>TOP ASSIST · APG</small></div><div><b><?= $rows?number_format(max(array_column($rows,'rebounds_avg')),1):'—' ?></b><small>TOP RIMBALZI · RPG</small></div></div><div class="table-scroll"><table><thead><tr><th>Giocatore</th><th>Ruolo</th><th>PT</th><th>RIM</th><th>AST</th><th>FG%</th><th>3P%</th><th>TL%</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['position']) ?></td><td><?= number_format($p['points_avg'],1) ?></td><td><?= number_format($p['rebounds_avg'],1) ?></td><td><?= number_format($p['assists_avg'],1) ?></td><td><?= number_format($p['fg_pct'],1) ?>%</td><td><?= number_format($p['three_pct'],1) ?>%</td><td><?= number_format($p['ft_pct'],1) ?>%</td></tr><?php endforeach; ?></tbody></table></div><p class="fine-print">Tutte le statistiche in questa pagina sono inventate per il prototipo.</p></section><?php require __DIR__.'/partials/footer.php'; ?>